namespace sv_e5e7f7b73429415a8531a807e502245b.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

/// <summary>
/// Mutable state container for the multi-step form, cascaded to child components.
/// </summary>
public class ApplicationFormState
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";

    public List<WorkEntryState> WorkEntries { get; set; } = [new()];

    public List<ReferenceState> References { get; set; } = [new(), new()];

    public string CoverLetter { get; set; } = "";
    public int CoverLetterMaxLength => 2000;

    public JobApplication ToJobApplication() => new(
        new PersonalInfo(FullName, Email, Phone, Address),
        new WorkHistory(WorkEntries.Select(w => new WorkEntry(
            w.Company, w.Title, w.StartDate, w.IsCurrent ? null : w.EndDate, w.Description)).ToList()),
        References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
        CoverLetter);
}

public class WorkEntryState
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime StartDate { get; set; } = DateTime.Today;
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferenceState
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

@using sv_e5e7f7b73429415a8531a807e502245b.Models

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="mb-3">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control" @bind="State.FullName" placeholder="John Doe" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control" @bind="State.Email" placeholder="john@example.com" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <div class="text-danger mt-1">@_emailError</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control" @bind="State.Phone" placeholder="(555) 123-4567" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <textarea class="form-control" rows="2" @bind="State.Address" placeholder="123 Main St, City, State ZIP"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="alert alert-danger">@_validationError</div>
    }

    <div class="d-flex justify-content-end mt-4">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @if (_isValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
                <span>Validating…</span>
            }
            else
            {
                <span>Next →</span>
            }
        </button>
    </div>
</div>

@code {
    [CascadingParameter] public required ApplicationFormState State { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(State.FullName) ||
            string.IsNullOrWhiteSpace(State.Email) ||
            string.IsNullOrWhiteSpace(State.Phone) ||
            string.IsNullOrWhiteSpace(State.Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        _isValidating = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(State.Email);
            if (!isValidEmail)
            {
                _emailError = "This email address is not valid.";
                return;
            }
        }
        finally
        {
            _isValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_e5e7f7b73429415a8531a807e502245b.Models

<div class="step-content">
    <h3>Work History</h3>

    @for (var i = 0; i < State.WorkEntries.Count; i++)
    {
        var index = i;
        var entry = State.WorkEntries[index];

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="card-title mb-0">Position @(index + 1)</h5>
                    @if (State.WorkEntries.Count > 1)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Company <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="entry.Company" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Job Title <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="entry.Title" />
                    </div>
                </div>

                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date <span class="text-danger">*</span></label>
                        <input type="date" class="form-control" @bind="entry.StartDate" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end mb-1">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" id="current-@index" @bind="entry.IsCurrent" />
                            <label class="form-check-label" for="current-@index">I currently work here</label>
                        </div>
                    </div>
                </div>

                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" @bind="entry.Description"></textarea>
                </div>
            </div>
        </div>
    }

    <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="alert alert-danger">@_validationError</div>
    }

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [CascadingParameter] public required ApplicationFormState State { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void AddEntry() => State.WorkEntries.Add(new WorkEntryState());

    private void RemoveEntry(int index) => State.WorkEntries.RemoveAt(index);

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var entry in State.WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Company and Job Title are required for each position.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_e5e7f7b73429415a8531a807e502245b.Models

<div class="step-content">
    <h3>References</h3>

    @for (var i = 0; i < State.References.Count; i++)
    {
        var index = i;
        var reference = State.References[index];

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h5 class="card-title mb-0">Reference @(index + 1)</h5>
                    @if (State.References.Count > 2)
                    {
                        <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Name <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="reference.Name" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Relationship <span class="text-danger">*</span></label>
                        <input type="text" class="form-control" @bind="reference.Relationship" placeholder="e.g., Former Manager" />
                    </div>
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Email <span class="text-danger">*</span></label>
                        <input type="email" class="form-control" @bind="reference.Email" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone <span class="text-danger">*</span></label>
                        <input type="tel" class="form-control" @bind="reference.Phone" />
                    </div>
                </div>
            </div>
        </div>
    }

    @if (State.References.Count < 3)
    {
        <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="alert alert-danger">@_validationError</div>
    }

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [CascadingParameter] public required ApplicationFormState State { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private void AddReference() => State.References.Add(new ReferenceState());

    private void RemoveReference(int index) => State.References.RemoveAt(index);

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var r in State.References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) ||
                string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_e5e7f7b73429415a8531a807e502245b.Models

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="mb-3">
        <label class="form-label">Write your cover letter below</label>
        <textarea class="form-control" rows="10" maxlength="@State.CoverLetterMaxLength"
                  @bind="State.CoverLetter" @bind:event="oninput"></textarea>
        <div class="form-text text-end">
            @(State.CoverLetter?.Length ?? 0) / @State.CoverLetterMaxLength characters
        </div>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="alert alert-danger">@_validationError</div>
    }

    <div class="d-flex justify-content-between mt-4">
        <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
    </div>
</div>

@code {
    [CascadingParameter] public required ApplicationFormState State { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? _validationError;

    private async Task HandleNext()
    {
        _validationError = null;

        if (string.IsNullOrWhiteSpace(State.CoverLetter))
        {
            _validationError = "A cover letter is required.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_e5e7f7b73429415a8531a807e502245b.Models

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (_submitted)
    {
        <div class="alert alert-success text-center py-4">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p>Your application has been received. Your application ID is:</p>
            <p class="display-6 fw-bold">@_applicationId</p>
        </div>
    }
    else
    {
        <!-- Personal Info -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm p-0" @onclick='() => OnGoToStep.InvokeAsync(0)'>Edit</button>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@State.FullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@State.Email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@State.Phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@State.Address</dd>
                </dl>
            </div>
        </div>

        <!-- Work History -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm p-0" @onclick='() => OnGoToStep.InvokeAsync(1)'>Edit</button>
            </div>
            <div class="card-body">
                @foreach (var entry in State.WorkEntries)
                {
                    <div class="mb-3 pb-2 border-bottom">
                        <div><strong>@entry.Title</strong> at @entry.Company</div>
                        <div class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                        </div>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <div class="mt-1">@entry.Description</div>
                        }
                    </div>
                }
            </div>
        </div>

        <!-- References -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm p-0" @onclick='() => OnGoToStep.InvokeAsync(2)'>Edit</button>
            </div>
            <div class="card-body">
                @foreach (var r in State.References)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> — @r.Relationship<br />
                        <span class="text-muted">@r.Email · @r.Phone</span>
                    </div>
                }
            </div>
        </div>

        <!-- Cover Letter -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm p-0" @onclick='() => OnGoToStep.InvokeAsync(3)'>Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@State.CoverLetter</p>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(_submitError))
        {
            <div class="alert alert-danger">@_submitError</div>
        }

        <div class="d-flex justify-content-between mt-4">
            <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @if (_isSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                    <span>Submitting…</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [CascadingParameter] public required ApplicationFormState State { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnGoToStep { get; set; }
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string? _submitError;

    private async Task HandleSubmit()
    {
        _submitError = null;
        _isSubmitting = true;

        try
        {
            _applicationId = await ApplicationService.SubmitApplicationAsync(State.ToJobApplication());
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

@page "/apply"
@rendermode InteractiveServer
@using sv_e5e7f7b73429415a8531a807e502245b.Models
@using sv_e5e7f7b73429415a8531a807e502245b.Components.Apply

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <!-- Step Indicator -->
    <nav class="step-indicator mb-4">
        @for (var i = 0; i < _stepNames.Length; i++)
        {
            var step = i;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;

            <div class="step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "")"
                 @onclick="() => GoToStep(step)" role="button">
                <div class="step-circle">
                    @if (isCompleted)
                    {
                        <span>✓</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <div class="step-label">@_stepNames[step]</div>
            </div>

            @if (step < _stepNames.Length - 1)
            {
                <div class="step-connector @(step < _currentStep ? "completed" : "")"></div>
            }
        }
    </nav>

    <!-- Step Content -->
    <CascadingValue Value="_formState">
